import time
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock=time.monotonic):
        self._capacity = capacity
        self._ttl = ttl
        self._clock = clock
        self._data = OrderedDict()  # key -> (value, expiry)

    def get(self, key):
        entry = self._data.get(key)
        if entry is None:
            return None
        value, expiry = entry
        if self._clock() >= expiry:
            del self._data[key]
            return None
        self._data.move_to_end(key)
        return value

    def put(self, key, value):
        now = self._clock()
        expiry = now + self._ttl
        if key in self._data:
            self._data[key] = (value, expiry)
            self._data.move_to_end(key)
            return
        if self._capacity <= 0:
            return
        if len(self._data) >= self._capacity:
            self._purge_expired()
            if len(self._data) >= self._capacity:
                self._data.popitem(last=False)
        self._data[key] = (value, expiry)

    def _purge_expired(self):
        now = self._clock()
        to_remove = [k for k, (_, expiry) in self._data.items() if now >= expiry]
        for k in to_remove:
            del self._data[k]

    def __len__(self):
        now = self._clock()
        return sum(1 for _, (_, expiry) in self._data.items() if now < expiry)
```

- **OrderedDict for LRU**: `move_to_end` and `popitem(last=False)` give O(1) LRU operations; the dict part gives O(1) key lookup.
- **Lazy expiry in `get`**: expired entries are removed on access, which also keeps `_purge_expired` amortized O(1) per operation (each entry is purged at most once).
- **`__len__` is O(n)**: the spec only requires O(1) amortized for `get`/`put`; counting live entries requires scanning since entries expire passively via the clock.

