import heapq

def shortest_path(n: int, edges: list[tuple[int, int, int]], src: int, dst: int) -> tuple[int | None, list[int]]:
    if src == dst:
        return (0, [src])

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra
    INF = float('inf')
    dist = [INF] * n
    prev = [-1] * n
    dist[src] = 0

    heap = [(0, src)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        if u == dst:
            break
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))

    if dist[dst] == INF:
        return (None, [])

    # Reconstruct path
    path = []
    node = dst
    while node != -1:
        path.append(node)
        node = prev[node]
    path.reverse()

    return (dist[dst], path)
```

- Used early termination: once `dst` is popped from the heap its distance is finalized, so we break immediately.
- Path reconstruction via `prev` array avoids storing full paths in the heap, keeping memory O(n) rather than O(n·path_length).
- Stale-entry check (`if d > dist[u]`) ensures each node is processed at most once in the inner loop, giving O((n + m) log n) overall.

