def eval_expr(s: str) -> float:
    n = len(s)
    pos = 0

    def skip_ws():
        nonlocal pos
        while pos < n and s[pos] in ' \t\n\r':
            pos += 1

    def parse_number():
        nonlocal pos
        skip_ws()
        if pos >= n:
            raise ValueError("Expected number")
        start = pos
        if s[pos] == '.':
            pos += 1
            if pos >= n or not s[pos].isdigit():
                raise ValueError("Invalid number")
            while pos < n and s[pos].isdigit():
                pos += 1
        elif s[pos].isdigit():
            while pos < n and s[pos].isdigit():
                pos += 1
            if pos < n and s[pos] == '.':
                pos += 1
                while pos < n and s[pos].isdigit():
                    pos += 1
        else:
            raise ValueError("Invalid character in expression")
        return float(s[start:pos])

    def parse_factor():
        nonlocal pos
        skip_ws()
        if pos >= n:
            raise ValueError("Unexpected end of expression")
        # Handle stacked unary operators iteratively
        neg_count = 0
        while pos < n and s[pos] in '+-':
            if s[pos] == '-':
                neg_count += 1
            pos += 1
            skip_ws()
        if pos >= n:
            raise ValueError("Unexpected end of expression")
        if s[pos] == '(':
            pos += 1
            result = parse_expr()
            skip_ws()
            if pos >= n or s[pos] != ')':
                raise ValueError("Unbalanced parentheses")
            pos += 1
        else:
            result = parse_number()
        if neg_count & 1:
            result = -result
        return result

    def parse_term():
        nonlocal pos
        result = parse_factor()
        while True:
            skip_ws()
            if pos < n and s[pos] in '*/':
                op = s[pos]
                pos += 1
                rhs = parse_factor()
                if op == '/':
                    if rhs == 0.0:
                        raise ZeroDivisionError("division by zero")
                    result /= rhs
                else:
                    result *= rhs
            else:
                break
        return result

    def parse_expr():
        nonlocal pos
        result = parse_term()
        while True:
            skip_ws()
            if pos < n and s[pos] in '+-':
                op = s[pos]
                pos += 1
                rhs = parse_term()
                if op == '+':
                    result += rhs
                else:
                    result -= rhs
            else:
                break
        return result

    result = parse_expr()
    skip_ws()
    if pos != n:
        raise ValueError("Unexpected trailing characters")
    return float(result)
```

- **Iterative unary handling**: Stacked unary `+`/`-` are consumed in a loop inside `parse_factor` to avoid recursion depth issues with long chains like `----...----2`.
- **Single-pass tokenizer via index pointer**: All scanning uses a shared `pos` index with `skip_ws`, giving O(n) time and O(1) extra space (besides the paren recursion stack bounded at 200).
- **Grammar naturally encodes precedence/associativity**: `expr → term (+ term)*` and `term → factor (* factor)*` give left-associative, correct-precedence evaluation without a shunting-yard or precedence-climbing approach.

