import heapq


def running_median(nums: list[int]) -> list[float]:
    if not nums:
        return []

    max_heap = []  # lower half (negated for min-heap behavior)
    min_heap = []  # upper half
    result = []

    for num in nums:
        if not max_heap or num <= -max_heap[0]:
            heapq.heappush(max_heap, -num)
        else:
            heapq.heappush(min_heap, num)

        # Rebalance: max_heap can have at most 1 more element than min_heap
        if len(max_heap) > len(min_heap) + 1:
            moved = -heapq.heappop(max_heap)
            heapq.heappush(min_heap, moved)
        elif len(min_heap) > len(max_heap):
            moved = heapq.heappop(min_heap)
            heapq.heappush(max_heap, -moved)

        # Compute median
        if len(max_heap) > len(min_heap):
            result.append(float(-max_heap[0]))
        else:
            result.append((-max_heap[0] + min_heap[0]) / 2.0)

    return result
```

- Uses two heaps (max-heap via negation for lower half, min-heap for upper half) giving O(n log n) total time.
- Maintains the invariant that `max_heap` has size equal to or one greater than `min_heap`, ensuring the median is always at the top of one or both heaps.
- All returned values are explicitly cast to `float` to satisfy the "always return floats" requirement.

