from decimal import Decimal, ROUND_HALF_UP

def invoice_total(items, country, code=None) -> float:
    vat_multipliers = {
        "DE": Decimal("1.19"),
        "FR": Decimal("1.20"),
        "GB": Decimal("1.20"),
        "US": Decimal("1"),
    }

    if not isinstance(country, str) or country not in vat_multipliers:
        raise ValueError("Unknown country")

    if code not in (None, "SAVE10", "FLAT5"):
        raise ValueError("Unknown discount code")

    try:
        iterator = iter(items)
    except TypeError as exc:
        raise ValueError("items must be iterable") from exc

    subtotal = Decimal("0")

    for item in iterator:
        try:
            price = Decimal(str(item["price"]))
            qty = Decimal(str(item["qty"]))
        except (TypeError, ValueError, KeyError) as exc:
            raise ValueError("Invalid item") from exc

        if not price.is_finite() or not qty.is_finite():
            raise ValueError("Invalid item")

        subtotal += price * qty

    if code == "SAVE10":
        subtotal *= Decimal("0.90")
    elif code == "FLAT5":
        subtotal = max(subtotal - Decimal("5.00"), Decimal("0"))

    total = subtotal * vat_multipliers[country]
    total = total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return float(total)
```

- Country validation is strict and unknown countries now raise `ValueError`.
- Discounts are applied to the pre-tax subtotal, with `FLAT5` clamped at zero.
- All monetary arithmetic uses `Decimal(str(x))`, and the final result is rounded to cents using `ROUND_HALF_UP`.

