from collections import deque

class RateLimiter:
    _window_seconds = 10.0
    _max_allowed = 5

    def __init__(self) -> None:
        self._allowed = {}

    def allow(self, user_id: str, now: float) -> bool:
        cutoff = now - self._window_seconds
        history = self._allowed.get(user_id)

        if history is None:
            history = deque()
            self._allowed[user_id] = history

        while history and history[0] <= cutoff:
            history.popleft()

        if len(history) < self._max_allowed:
            history.append(now)
            return True

        return False
```

- Timestamps at or before `now - 10` are discarded because they can never count for future windows.
- Only allowed requests are stored, so denied requests do not consume quota.
- Each user keeps at most 5 timestamps, giving bounded per-user memory.
